import pandas as pd
df = pd.DataFrame({'Height': [73.8, 68.8, 63.5, 66.2], 'Weight': [241.9, 162.3, 135.8, 155.1]})
assert column_summary(df, 'Weight') == {'mean': 173.78, 'median': 158.7, 'min': 135.8, 'max': 241.9}

solution.code:
def column_summary(df, col):
    s = df[col]
    return {'mean': round(float(s.mean()), 2), 'median': round(float(s.median()), 2),
            'min': round(float(s.min()), 2), 'max': round(float(s.max()), 2)}

