import pandas as pd, numpy as np
d = pd.DataFrame({'a': [1, 2, 3], 'b': [np.nan, np.nan, 1], 'c': [np.nan, 5, 6]})
assert missing_report(d) == {'b': 66.7, 'c': 33.3}

solution.code:
def missing_report(df):
    pct = (df.isna().mean() * 100).round(1)
    return {col: float(v) for col, v in pct.items() if v > 0}
